settings.custom_liquid:
{% assign features_media = product.metafields.custom.wetsuit_features %}

{% if features_media != blank %}
  <div class="features-media-grid">
    {% for file in features_media.value %}
      {% if file.media_type == 'image' %}
        {{ file | image_url: width: 1600 | image_tag: loading: 'lazy', alt: product.title }}
      {% elsif file.media_type == 'video' %}
        {{ file | media_tag: controls: true, autoplay: false, loop: false, muted: false }}
      {% else %}
        <a href="{{ file | file_url }}" target="_blank">{{ file.filename }}</a>
      {% endif %}
    {% endfor %}
  </div>
{% endif %}

{% assign video_url = product.metafields.custom.wetsuit_videos | strip %}

{% if video_url %}
  {%- comment -%} Normalize to a YouTube ID {%- endcomment -%}
  {% assign tmp = video_url | replace: '/shorts/', '/watch?v=' %}
  {% assign youtube_id = '' %}

  {% if tmp contains 'youtu.be/' %}
    {% assign youtube_id = tmp | split: 'youtu.be/' | last | split: '?' | first | split: '&' | first %}
  {% elsif tmp contains 'watch?v=' %}
    {% assign youtube_id = tmp | split: 'watch?v=' | last | split: '&' | first %}
  {% elsif tmp contains '/embed/' %}
    {% assign youtube_id = tmp | split: '/embed/' | last | split: '?' | first | split: '&' | first %}
  {% endif %}

  {% if youtube_id != '' %}
    <div class="product-video-embed">
      <iframe
        src="https://www.youtube-nocookie.com/embed/{{ youtube_id }}"
        title="Product video"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowfullscreen
        loading="lazy"></iframe>
    </div>
  {% endif %}
{% endif %}
